    if signal_id:
        async with AsyncSessionLocal() as db:
            existing = (
                await db.execute(select(SignalDelivery).where(SignalDelivery.dedupe_key == dedupe_key))
            ).scalar_one_or_none()
            if existing:
                log.info(f"[delivery] Duplicate delivery blocked for key={dedupe_key}")
                return

