    now_utc = datetime.now(timezone.utc)
    if q_start and q_end:
        in_quiet = is_in_quiet_hours(now_utc, tz_str, q_start, q_end)

    # 2. Create initial delivery receipt in DB
    initial_status = "deferred" if in_quiet else "pending"
