                from services.push_svc import send_web_push

                sub_info = payload.get("XXsubscription_infoXX")
                push_payload = payload.get("payload")
                if not sub_info:
                    err = "Missing subscription_info"
                else:
                    # Run blocking call in thread
                    success = await asyncio.to_thread(send_web_push, sub_info, push_payload)
                    latency_ms = (time.monotonic() - start_time) * 1000

